-- Generated by scripts/import/build-thumbnail-sql.ts — do not hand-edit.
-- Poster source URLs for 3415 clips. Idempotent.
--
-- A PERMANENT table, not a temporary one: the fetching is done afterwards in
-- bounded batches by public.fill_thumbnails(), because ~850 sequential HTTP
-- calls cannot finish inside one statement. The list has to outlive the
-- session that loads it.
--
-- Internal: no grants are issued, so RLS-less as it is, anon still cannot
-- read it — nothing reaches a client from here.

create table if not exists public.thumb_src (
  clip_id text primary key,
  url     text not null
);

on conflict (clip_id) do nothing;

